"""Strata ladder: driver of the Kaggle kernel (generated by build_kernel.py, which embeds this file).

    smoke   exactness on the GPU (features, test B), bytes/s and updates/s per rung and batch size, resume check,
            learning-rate probe, export + reference check (test C), one selection file; <= 30 minutes in total
    long    one training run per GPU (one seed each) inside a minutes budget, then export, reference check and
            one selection file; everything needed to evaluate locally is written to the work directory

Every step is a subprocess with its own log file and a timeout taken from the time left, so the script always
ends by itself, well before the session limit. Reads its configuration from kernel-config.json next to it.
"""
import csv
import glob
import json
import os
import shutil
import subprocess
import sys
import threading
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import corpus  # noqa: E402

T_START = time.time()
with open(os.path.join(HERE, "kernel-config.json")) as _f:
    CFG = json.load(_f)
WORK = CFG["work"]
SRC_ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
DATA = CFG["data_root"] or os.path.join(SRC_ROOT, "data", "strata", "ladder")
SELECT_LOG = os.path.join(SRC_ROOT, "data", "strata", "raw", "loghub", "Zookeeper.log")
REPORT = {"mode": CFG["mode"], "steps": []}


def minutes_left():
    return CFG["deadline_minutes"] - (time.time() - T_START) / 60


def log(msg):
    print(f"[{(time.time() - T_START) / 60:6.1f} min] {msg}", flush=True)


def save_report():
    with open(os.path.join(WORK, f"{CFG['mode']}-report.json"), "w") as f:
        json.dump(REPORT, f, indent=1)


def step(name, script, args, gpu=None, reserve=1.0):
    """Run one tool as a subprocess; its output goes to WORK/logs/<name>.log. Returns True on exit status 0."""
    left = minutes_left() - reserve
    rec = {"name": name, "args": " ".join(args), "gpu": gpu}
    REPORT["steps"].append(rec)
    if left <= 0.5:
        rec["status"] = "SKIPPED (no time left)"
        log(f"{name}: skipped, no time left")
        return False
    env = dict(os.environ)
    if gpu is not None:
        env["CUDA_VISIBLE_DEVICES"] = str(gpu)
    t0 = time.time()
    path = os.path.join(WORK, "logs", name + ".log")
    with open(path, "w") as out:
        try:
            rc = subprocess.run([sys.executable, os.path.join(HERE, script)] + args, stdout=out,
                                stderr=subprocess.STDOUT, env=env, timeout=left * 60).returncode
        except subprocess.TimeoutExpired:
            rc = "timeout"
    with open(path) as f:
        tail = f.read().strip().splitlines()[-12:]
    rec.update(status="ok" if rc == 0 else f"FAILED ({rc})", seconds=round(time.time() - t0, 1), tail=tail)
    log(f"{name}: {rec['status']} in {rec['seconds']} s | " + (tail[-1][:200] if tail else ""))
    save_report()
    return rc == 0


def per_gpu(queues):
    """Run one queue of callables per GPU at the same time (one process per GPU at any moment)."""
    threads = [threading.Thread(target=lambda q=q: [job() for job in q]) for q in queues if q]
    for t in threads:
        t.start()
    for t in threads:
        t.join()


def train_args(rung, out, updates, batch, minutes, seed, lr, extra=()):
    return ["--rung", rung, "--data", DATA, "--out", os.path.join(WORK, out), "--device", CFG["device"],
            "--updates", str(updates), "--batch", str(batch), "--minutes", str(minutes), "--seed", str(seed),
            "--lr", str(lr), "--chunk", str(CFG["chunk"]), *extra]


def summary(out):
    path = os.path.join(WORK, out, "summary.json")
    if not os.path.isfile(path):
        return None
    with open(path) as f:
        return json.load(f)


def read_log(out):
    with open(os.path.join(WORK, out, "train_log.csv")) as f:
        return [[float(v) for v in row[3:]] for row in list(csv.reader(f))[1:]]


def finish_run(out, gpu):
    """Export + reference check (CPU) and one selection file for a finished or paused run."""
    ckpt = os.path.join(WORK, out, "ckpt.pt")
    if not os.path.isfile(ckpt):
        return
    step(f"{out}-export", "export.py", ["--ckpt", ckpt, "--out", os.path.join(WORK, out, "weights-int.npz"),
                                        "--check", "sel-zookeeper", "--bytes", str(CFG["check_bytes"])], gpu)
    step(f"{out}-eval", "run_eval.py", ["--ckpt", ckpt, "--sources", "sel-zookeeper", "--device", "cpu",
                                        "--bytes", str(CFG["eval_bytes"]), "--minutes", "6"], gpu)


def smoke(gpus):
    cfg = CFG["smoke"]
    g0 = gpus[0]
    step("features", "check_exact.py", ["--test", "features", "--data", DATA, "--device", CFG["device"]], g0)
    for rung in cfg["exact_rungs"]:
        step(f"exact-{rung}", "check_exact.py", ["--test", "B", "--data", DATA, "--rung", rung, "--device",
                                                 CFG["device"], "--streams", "48", "--windows", "3"], g0)
    queues = [[] for _ in gpus]
    for i, (rung, batch) in enumerate(cfg["probes"]):
        out = f"probe-{rung}-b{batch}"
        queues[i % len(gpus)].append(lambda r=rung, b=batch, o=out, g=gpus[i % len(gpus)]: step(
            o, "run_train.py", train_args(r, o, cfg["probe_updates"], b, 5, 1204, CFG["lr"]), g))
    per_gpu(queues)
    REPORT["throughput"] = [summary(f"probe-{r}-b{b}") for r, b in cfg["probes"]]
    rung, batch, upd = cfg["rung"], cfg["batch"], cfg["updates"]
    lrs = cfg["lrs"]
    queues = [[lambda: step("run-a", "run_train.py", train_args(rung, "run-a", upd, batch, 9, 1204, CFG["lr"]), g0)],
              [lambda: step("run-b1", "run_train.py", train_args(rung, "run-b", upd, batch, 9, 1204, CFG["lr"],
                                                                 ["--session-updates", str(upd // 2)]), gpus[-1]),
               lambda: step("run-b2", "run_train.py", train_args(rung, "run-b", upd, batch, 9, 1204, CFG["lr"]),
                            gpus[-1])]]
    for i, lr in enumerate(lrs):
        queues[i % 2].append(lambda lr=lr, g=(g0, gpus[-1])[i % 2]: step(
            f"lr-{lr}", "run_train.py", train_args(rung, f"lr-{lr}", upd, batch, 9, 1204, lr), g))
    if len(gpus) == 1:
        queues = [queues[0] + queues[1]]
    per_gpu(queues)
    if summary("run-a") and summary("run-b") and summary("run-b")["updates_done"] >= upd:
        a, b = read_log("run-a"), read_log("run-b")
        REPORT["resume_max_cost_diff"] = max(abs(x - y) for ra, rb in zip(a, b) for x, y in zip(ra, rb))
        log(f"resume check: max |cost difference| uninterrupted vs resumed = {REPORT['resume_max_cost_diff']:.4f}")
    REPORT["lr_probe"] = {str(lr): (summary(f"lr-{lr}") or {}).get("final_costs") for lr in lrs}
    REPORT["lr_probe"][str(CFG["lr"])] = (summary("run-a") or {}).get("final_costs")
    ckpt = os.path.join(WORK, "run-a", "ckpt.pt")
    if os.path.isfile(ckpt):
        step("exact-trained", "check_exact.py", ["--test", "B", "--data", DATA, "--rung", rung, "--ckpt", ckpt,
                                                 "--device", CFG["device"], "--streams", "48", "--windows", "3"], g0)
    finish_run("run-a", g0)


def long_run(gpus):
    cfg = CFG["long"]
    runs = [f"run-{cfg['rung']}-s{seed}" for seed in cfg["seeds"][:len(gpus)]]
    for out in runs:                                  # continue a previous session's checkpoint when one is attached
        for src in glob.glob(os.path.join(cfg["resume_glob"], out)) if cfg["resume_glob"] else []:
            shutil.copytree(src, os.path.join(WORK, out), dirs_exist_ok=True)
            log(f"{out}: checkpoint copied from an attached dataset")
    budget = min(cfg["minutes"], minutes_left() - cfg["tail_minutes"])
    queues = [[lambda o=out, s=seed, g=g: step(o, "run_train.py", train_args(
        cfg["rung"], o, cfg["updates"], cfg["batch"], budget, s, CFG["lr"]), g, reserve=cfg["tail_minutes"] - 5)]
        for out, seed, g in zip(runs, cfg["seeds"], gpus)]
    per_gpu(queues)
    REPORT["runs"] = [summary(out) for out in runs]
    per_gpu([[lambda o=out, g=g: finish_run(o, g)] for out, g in zip(runs, gpus)])


def main():
    os.makedirs(os.path.join(WORK, "logs"), exist_ok=True)
    import torch
    n_gpu = torch.cuda.device_count() if CFG["device"] == "cuda" else 0
    REPORT["torch"] = torch.__version__
    REPORT["gpus"] = [torch.cuda.get_device_name(i) for i in range(n_gpu)]
    REPORT["cpus"] = os.cpu_count()
    log(f"mode {CFG['mode']}, torch {torch.__version__}, GPUs {REPORT['gpus']}, {os.cpu_count()} CPUs")
    if CFG["device"] == "cuda" and n_gpu == 0:
        raise SystemExit("no GPU in this session: nothing was run")
    sizes = {k: v * 1_000_000 for k, v in CFG["data_mb"].items()}
    REPORT["training_bytes"] = corpus.fetch(DATA, sizes)
    if not os.path.isfile(SELECT_LOG):
        os.makedirs(os.path.dirname(SELECT_LOG), exist_ok=True)
        corpus.fetch_log("Zookeeper", SELECT_LOG, 2_000_000)      # selection source: evaluation only, never trained
    log(f"data ready: {REPORT['training_bytes']:,d} training bytes")
    gpus = list(range(n_gpu)) or [None]
    if CFG["mode"] == "smoke":
        smoke(gpus)
    else:
        long_run(gpus)
    REPORT["minutes"] = round((time.time() - T_START) / 60, 1)
    save_report()
    log("report: " + json.dumps({k: v for k, v in REPORT.items() if k != "steps"})[:3000])
    failed = [s["name"] for s in REPORT["steps"] if s.get("status") != "ok"]
    log("KERNEL DONE" + (f" (not ok: {failed})" if failed else " (every step ok)"))


if __name__ == "__main__":
    main()
